<script setup lang="ts">
import {displayText,displayJson,initials} from "../stores/presentation"
import VoiceInterview from '../components/VoiceInterview.vue'
import {computed,ref,onMounted} from 'vue'
import {inr,label} from '../stores/desk'
const emit=defineEmits(['staff','home'])
const profiles=ref<any[]>([]),profile=ref<any>(null),chosen=ref('SYN-0001'),session=ref(sessionStorage.getItem('borrower_token')||'')
const challenge=ref<any>(null),code=ref(''),kyc=ref(''),kycChallenge=ref<any>(null),kycCode=ref(''),cases=ref<any[]>([]),active=ref<any>(null),busy=ref(false),error=ref(''),step=ref(1),newCase=ref(false),notice=ref('')
const pan=ref(''),dob=ref(''),purpose=ref('Purchase equipment to grow our business'),amount=ref(1000000),tenure=ref(36),loanType=ref('term'),consents=ref<string[]>([]),response=ref(''),docKind=ref('gst'),replacement=ref('')
const requestedTotal=computed(()=>cases.value.reduce((sum,a)=>sum+Number(a.data.requested_amount),0))
const awaitingCount=computed(()=>cases.value.filter(a=>!['approved','rejected'].includes(a.status)).length)
const consentOptions=[['kyc','Identity and business verification'],['bank','Bank statement retrieval'],['tax','GST and ITR retrieval'],['bureau','Bureau report retrieval'],['processing','Processing data for this application']]
async function call(path:string,body?:any){const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+session.value,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json().catch(()=>{throw Error('Service unavailable. Please try again shortly.')});if(!r.ok)throw Error(d.detail||'Request failed');return d}
async function work(fn:()=>Promise<any>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){const d=await call('/borrower/applications');profile.value=d.profile;cases.value=d.items;if(active.value)active.value=cases.value.find(x=>x.id===active.value.id);pan.value=d.profile.pan;dob.value=d.profile.dob}
async function requestLogin(){await work(async()=>{const p=profiles.value.find(x=>x.id===chosen.value);challenge.value=await call('/demo/otp/request',{mobile:p.mobile,purpose:'login'});code.value=''})}
async function login(){await work(async()=>{const d=await call('/demo/otp/verify',{challenge_id:challenge.value.challenge_id,code:code.value});session.value=d.token;sessionStorage.setItem('borrower_token',d.token);await load();newCase.value=!cases.value.length})}
async function logout(){await work(()=>call('/borrower/logout',{}));session.value='';sessionStorage.removeItem('borrower_token');profile.value=null;active.value=null;challenge.value=null;kyc.value=''}
async function requestKyc(){await work(async()=>{kycChallenge.value=await call('/demo/otp/request',{mobile:profile.value.mobile,purpose:'kyc'});kycCode.value=''})}
async function verifyKyc(){await work(async()=>{const d=await call('/demo/otp/verify',{challenge_id:kycChallenge.value.challenge_id,code:kycCode.value});kyc.value=d.kyc_proof;step.value=2})}
function start(){newCase.value=true;active.value=null;step.value=1;kyc.value='';kycChallenge.value=null;consents.value=[]}
async function submit(){await work(async()=>{active.value=await call('/borrower/applications',{kyc_proof:kyc.value,pan:pan.value,dob:dob.value,purpose:purpose.value,requested_amount:amount.value,tenure_months:tenure.value,loan_type:loanType.value,consents:consents.value});newCase.value=false;await load();active.value=await call('/borrower/applications/'+active.value.id+'/fetch',{});await load()})}
async function refreshFetch(){await work(async()=>{active.value=await call('/borrower/applications/'+active.value.id+'/fetch',{});await load()})}
async function upload(e:Event){const input=e.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;await work(async()=>{const form=new FormData();form.append('data',f);const r=await fetch('/api/borrower/applications/'+active.value.id+'/documents?kind='+docKind.value+(replacement.value?'&replaces='+replacement.value:''),{method:'POST',headers:{Authorization:'Bearer '+session.value},body:form});const d=await r.json().catch(()=>{throw Error('Service unavailable. Please try again shortly.')});if(!r.ok)throw Error(d.detail||'Upload failed');active.value=d;replacement.value='';await load()});input.value=''}
async function sendResponse(){await work(async()=>{const r=await call('/borrower/applications/'+active.value.id+'/responses',{message:response.value});notice.value=r.message;response.value='';await load()})}
onMounted(()=>work(async()=>{profiles.value=(await call('/demo/profiles')).items;if(session.value){try{await load()}catch{session.value='';sessionStorage.removeItem('borrower_token')}}}))
</script>
<template><div class="borrower-shell"><header class="portal-header"><a class="product-brand" href="#" @click.prevent="emit('home')"><span class="logo-glyph">m<span>·</span></span><span>MSME<span class="brand-subtitle">CAPITAL</span></span></a><div class="portal-nav"><span class="nav-label">Business finance, thoughtfully.</span><button class="staff-link" @click="emit('staff')">Credit workspace <span>↗</span></button><button v-if="session" @click="logout">Sign out</button></div></header><main class="borrower-main"><div v-if="error" role="alert" class="error-banner">{{displayText(error)}}</div><div v-if="notice" class="notice">{{displayText(notice)}}</div><div v-if="busy" role="status" class="notice processing-notice"><span class="loading-dot"></span> Bringing everything together. Please keep this page open.</div>
<div v-if="!session" class="borrower-welcome"><div class="hero-story"><div class="eyebrow"><span class="eyebrow-line"></span> BUILT FOR YOUR NEXT CHAPTER</div><h1>Big ambitions.<br><em>Clearer possibilities.</em></h1><p>A thoughtful path to business finance. Bring your records together, understand your application and move forward with confidence.</p><div class="hero-pills"><span>✓ One connected application</span><span>✓ A team behind your journey</span></div><div class="growth-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-grid"></div><div class="art-step step-one"></div><div class="art-step step-two"></div><div class="art-step step-three"></div><div class="art-step step-four"></div><div class="art-caption"><span class="art-dot"></span> Room for what comes next.</div><div class="art-float float-one"><span>↗</span><div>Your business<br><strong>Your next chapter</strong></div></div><div class="art-float float-two">✦ <span>Progress, with perspective.</span></div></div></div>
<form class="panel welcome-card" @submit.prevent="challenge?login():requestLogin()"><div class="card-kicker">LET’S GET STARTED</div><h2>Your next move<br>starts here.</h2><p>Choose your business account to continue your application or start a new one.</p><label>Business account<select v-model="chosen" @change="challenge=null"><option v-for="p in profiles" :value="p.id">{{displayText(displayText(p.business))}}</option></select></label><div class="account-preview"><span class="company-avatar">{{displayText(initials(profiles.find(p=>p.id===chosen)?.business))}}</span><div><strong>{{displayText(displayText(profiles.find(p=>p.id===chosen)?.name))}}</strong><small>Mobile ending {{displayText(profiles.find(p=>p.id===chosen)?.mobile.slice(-4))}}</small></div><span class="account-check">✓</span></div><template v-if="challenge"><div class="otp-callout"><span>One-time access code</span><strong>{{displayText(challenge.demo_otp)}}</strong><small>Valid for five minutes</small></div><label>Enter verification code<input v-model="code" class="otp-input" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required placeholder="000000"></label></template><button class="primary full-width" :disabled="busy">{{displayText(challenge?'Verify & continue':'Continue to verification')}} <span>→</span></button><button v-if="challenge" class="text-button" type="button" @click="requestLogin" :disabled="busy">Request a new code</button><div class="login-footnote">Your application. Your pace.<br>Pick up where you left off, whenever you’re ready.</div></form></div>
<template v-else-if="profile"><div class="page-heading borrower-heading"><div><div class="eyebrow">YOUR BUSINESS FINANCE WORKSPACE</div><h1>Good to see you, {{displayText(displayText(profile.name).split(' ')[0])}}<span class="accent-period">.</span></h1><p>{{displayText(displayText(profile.business))}} · Let’s move your business forward.</p></div><button class="primary" @click="start" :disabled="busy">＋ New application</button></div><div v-if="!newCase" class="borrower-metrics"><div><span>YOUR APPLICATIONS</span><strong>{{displayText(cases.length.toString().padStart(2,'0'))}}</strong></div><div><span>REQUESTED FINANCE</span><strong>{{displayText(inr(requestedTotal))}}</strong></div><div><span>IN PROGRESS</span><strong>{{displayText(awaitingCount.toString().padStart(2,'0'))}}</strong></div><div class="metric-aside"><span class="spark-mark">✦</span><p>A clearer view<br>of your next step.</p></div></div>
<div class="tabs"><button :class="{active:!newCase}" @click="newCase=false">My applications</button><button v-if="newCase" class="active">New application</button></div>
<section v-if="newCase" class="panel intake"><div class="wizard-steps"><span v-for="(s,i) in ['Your identity','Your business','Your finance']" :class="{current:step===i+1,complete:step>i+1}"><b>{{displayText(step>i+1?'✓':i+1)}}</b>{{displayText(s)}}</span></div>
<form v-if="step===1" @submit.prevent="kycChallenge?verifyKyc():requestKyc()"><div class="form-heading"><span>01 / IDENTITY</span><h2>Start with you.</h2><p>Review the identity details linked to your business account.</p></div><div class="form-grid"><label>Full name<input :value="displayText(profile.name)" readonly></label><label>Date of birth<input v-model="dob" type="date" required></label><label>PAN reference<input :value="displayText(pan)" readonly></label><label>Mobile number<input :value="profile.mobile" readonly></label></div><template v-if="kycChallenge"><div class="otp-callout"><span>Identity verification code</span><strong>{{displayText(kycChallenge.demo_otp)}}</strong></div><label>Identity code<input class="otp-input" v-model="kycCode" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required placeholder="000000"></label></template><div class="form-actions"><button class="primary" :disabled="busy">{{displayText(kycChallenge?'Verify identity & continue':'Get verification code')}} →</button><button v-if="kycChallenge" type="button" @click="requestKyc" :disabled="busy">Request a new code</button></div></form>
<div v-if="step===2"><div class="form-heading"><span>02 / BUSINESS</span><h2>A little about your business.</h2><p>Review your business records and choose how we can access information for this application.</p></div><div class="form-grid"><label>Business name<input :value="displayText(profile.business)" readonly></label><label>Sector<input :value="profile.sector" readonly></label><label>Udyam reference<input :value="displayText(profile.udyam)" readonly></label><label>GST reference<input :value="displayText(profile.gstin)" readonly></label></div><div class="consent-list"><label v-for="[value,text] in consentOptions" class="checkbox"><input type="checkbox" :value="value" v-model="consents"><span>I agree to {{displayText(text.toLowerCase())}}.</span></label></div><div class="form-actions"><button @click="step=1">← Back</button><button class="primary" :disabled="consents.length!==5" @click="step=3">Continue to loan configuration →</button></div></div>
<form v-if="step===3" @submit.prevent="submit"><div class="form-heading"><span>03 / FINANCE</span><h2>Make room for your next move.</h2><p>Tell us what you’re building and the finance you need to get there.</p></div><div class="form-grid"><label>Loan type<select v-model="loanType"><option value="term">Term loan</option><option value="working_capital">Working capital</option><option value="lap">Loan against property</option><option value="construction">Construction</option></select></label><label>Requested amount (INR)<input v-model.number="amount" type="number" min="1" max="100000000" required></label><label>Tenure (months)<input v-model.number="tenure" type="number" min="1" max="120" required></label></div><label>What will the funds support?<textarea v-model="purpose" minlength="3" maxlength="500" required></textarea></label><div class="loan-preview"><span>YOUR REQUEST</span><strong>{{displayText(inr(amount))}}</strong><small>Over {{displayText(tenure)}} months · Subject to credit review</small></div><p v-if="['lap','construction'].includes(loanType)">A property survey, title review and margin assessment will be required.</p><div class="notice">We’ll bring together your consented records and prepare your application for the credit team.</div><div class="form-actions"><button type="button" @click="step=2">← Back</button><button class="primary" :disabled="busy||!kyc">Submit application →</button></div></form></section>
<template v-else><div class="panel applications-panel"><div class="section-title"><div><span class="card-kicker">YOUR NEXT CHAPTER</span><h2>Applications at a glance</h2></div><span class="subtle">{{displayText(cases.length)}} applications</span></div><div v-for="a in cases" class="application-tile"><span class="company-avatar">{{displayText(initials(a.data.business))}}</span><div><strong>{{displayText(displayText(a.data.business))}}</strong><small>{{displayText(a.id.slice(0,8).toUpperCase())}} · {{displayText(inr(a.data.requested_amount))}} · {{displayText(a.data.tenure_months)}} months</small></div><span class="badge" :class="a.status">{{displayText(label(a.status))}}</span><button class="track-button" @click="active=a">View application ↗</button></div><div v-if="!cases.length" class="empty"><span class="empty-symbol">↗</span><h3>Your next chapter starts here.</h3><p>Tell us about your business and we’ll guide you through the next steps.</p><button class="primary" @click="start">Start an application</button></div></div>
<section v-if="active"><div class="page-heading"><div><div class="eyebrow">APPLICATION {{displayText(active.id.slice(0,8).toUpperCase())}}</div><h2>Your progress, in one place.</h2><p>{{displayText(label(active.status))}}</p></div><button @click="work(load)" :disabled="busy">Refresh status ↻</button></div><div v-if="active.mock_ledger_posted" class="notice success">Your application has been approved and the sanction recorded. Review the agreed terms with your credit team.</div><VoiceInterview :key="active.id" :case-id="active.id" :revision="active.revision" :disabled="['approved','rejected','processing'].includes(active.status)" borrower @changed="work(load)"/><div class="source-grid"><div class="source-card" v-for="(s,k) in active.sources"><span class="source-icon">{{displayText(s.status==='fetched'?'✓':'!')}}</span><div><h3>{{displayText(String(k).toUpperCase())}}</h3><small>{{displayText(s.status==='fetched'?'Records received':'Action needed')}}</small></div><span class="source-indicator" :class="s.status"></span></div></div><button v-if="!['approved','rejected'].includes(active.status)" @click="refreshFetch" :disabled="busy">Refresh connected records</button><div class="panel next-step-panel"><span class="card-kicker">A CLEAR NEXT STEP</span><h2>What happens next?</h2><p v-if="!active.verification_complete">Your credit officer will review your identity, business and use of funds.</p><div v-for="r in active.requests" class="gap">{{displayText(r.data.message)}}</div><div v-for="c in active.checks.filter((x:any)=>x.result!=='pass')" class="gap"><strong>{{displayText(label(c.rule_id.toLowerCase()))}}</strong> · {{displayText(c.reason)}}</div><p v-if="active.status==='rejected'">Contact your credit team to discuss the decision and possible next steps.</p><p v-if="active.status==='awaiting_review'">Your application is with the credit team. We’ll keep your progress here up to date.</p><p v-if="active.status==='approved'">Your sanction is recorded. Your credit team can help with the next steps.</p></div>
<div class="panel" v-if="!['approved','rejected'].includes(active.status)"><h2>Keep your application moving.</h2><p>Share requested documents or a clarification with your credit officer. Select a replacement when correcting an existing record.</p><div class="form-grid"><label>Document type<select v-model="docKind" @change="replacement=''"><option v-for="k in ['bank','gst','itr','financial','kyc']">{{displayText(k)}}</option></select></label><label>Replace existing document<select v-model="replacement"><option value="">Add missing evidence</option><option v-for="d in active.documents.filter((d:any)=>d.kind===docKind&&d.status!=='superseded')" :value="d.id">{{displayText(d.name)}}</option></select></label></div><input aria-label="Upload additional evidence" type="file" accept=".pdf" @change="upload" :disabled="busy"><label>Message for your credit officer<textarea v-model="response" maxlength="2000" placeholder="Add context or respond to a question…"></textarea></label><button class="primary" @click="sendResponse" :disabled="busy||response.trim().length<3">Send clarification →</button></div></section></template></template><footer class="borrower-footer"><span>MSME Capital</span><span>Built around your business.</span></footer></main></div></template>
